/**
 * Exercises with start/end photos in public/exercises/ (from free-exercise-db, public
 * domain). Generated by scripts/fetch_exercise_images.py; exercises not listed here fall
 * back to the stick-figure animation.
 */
export const PHOTO_EXERCISES: ReadonlySet<string> = new Set([
  'push-up', 'incline-push-up', 'bench-press', 'dumbbell-bench-press', 'machine-chest-press', 'cable-fly',
  'pull-up', 'chin-up', 'lat-pulldown', 'barbell-row', 'dumbbell-row', 'seated-cable-row', 'deadlift',
  'overhead-press', 'dumbbell-shoulder-press', 'lateral-raise', 'front-raise', 'shrug',
  'dumbbell-curl', 'barbell-curl', 'hammer-curl', 'band-curl', 'bench-dip', 'parallel-dip',
  'overhead-triceps-extension', 'triceps-pushdown', 'diamond-push-up',
  'bodyweight-squat', 'goblet-squat', 'barbell-squat', 'lunge', 'bulgarian-split-squat', 'leg-press',
  'leg-extension', 'leg-curl', 'romanian-deadlift', 'glute-bridge', 'hip-thrust', 'kettlebell-swing',
  'calf-raise', 'plank', 'crunch', 'lying-leg-raise', 'mountain-climber', 'jumping-jack', 'high-knees', 'jump-rope',
]);

export const PHOTO_CREDIT = 'Exercise photos: free-exercise-db (public domain)';

/** [start, end] photo URLs, or null if the exercise has no photos. */
export function photoUrls(exerciseId: string, base = import.meta.env.BASE_URL ?? '/'): [string, string] | null {
  if (!PHOTO_EXERCISES.has(exerciseId)) return null;
  return [`${base}exercises/${exerciseId}-0.webp`, `${base}exercises/${exerciseId}-1.webp`];
}
